const { currentToken } = require('/tmp/tmpsbd3g9wk/auth.js');

function makeStore(init) {
  const m = new Map(Object.entries(init));
  return {
    get: (k) => m.get(k),
    set: (k, v) => m.set(k, v),
    clear: () => m.clear(),
    dump: () => Object.fromEntries(m),
  };
}

const expired = () => ({ access: { value: 'old', expiresAt: 0 }, refresh: { value: 'R0' } });

let calls = 0;
let lastOpts = null;
let respond = null;
globalThis.fetch = (url, opts) => {
  calls++;
  lastOpts = opts;
  return respond(url, opts);
};
const ok = (body) => Promise.resolve({ status: 200, ok: true, json: async () => body });
const status = (s) => Promise.resolve({ status: s, ok: false, json: async () => ({}) });

(async () => {
  // 1. Two concurrent callers, expired access token
  let n = 0;
  respond = () => ok({ access_token: 'T' + ++n, expires_in: 3600, refresh_token: 'R' + n });
  const s1 = makeStore(expired());
  const [a, b] = await Promise.all([currentToken(s1), currentToken(s1)]);
  console.log('1. concurrent:', { fetchCalls: calls, a, b, stored: s1.dump() });
  console.log('   request sent:', lastOpts);

  // 2. Refresh endpoint returns 401
  calls = 0;
  respond = () => status(401);
  const s2 = makeStore(expired());
  await currentToken(s2).catch((e) => console.log('2. error:', e.message));
  console.log('2. store after:', s2.dump());

  // 3. Refresh endpoint returns 400 (RFC 6749 invalid_grant style)
  respond = () => status(400);
  const s3 = makeStore(expired());
  await currentToken(s3).catch((e) => console.log('3. error:', e.message));
  console.log('3. store after:', s3.dump());

  // 4. Refresh request never settles
  respond = () => new Promise(() => {});
  const s4 = makeStore(expired());
  const r4 = await Promise.race([
    currentToken(s4).then(() => 'resolved', () => 'rejected'),
    new Promise((r) => setTimeout(() => r('still pending after 1s'), 1000)),
  ]);
  console.log('4. hang:', r4);

  // 5. expires_in below SKEW_MS (30s): does every call refresh?
  calls = 0;
  respond = () => ok({ access_token: 'short', expires_in: 20 });
  const s5 = makeStore(expired());
  await currentToken(s5);
  await currentToken(s5);
  await currentToken(s5);
  console.log('5. three calls with expires_in=20, fetch count:', calls);
})();

const { currentToken } = require('/tmp/tmpsbd3g9wk/auth.js');

const store = () => {
  const m = new Map([['access', { value: 'old', expiresAt: 0 }], ['refresh', { value: 'R0' }]]);
  return { get: (k) => m.get(k), set: (k, v) => m.set(k, v), clear: () => m.clear() };
};

let calls = 0;
let respond = () => new Promise(() => {}); // first refresh never settles
globalThis.fetch = () => {
  calls++;
  return respond();
};

const withTimeout = (p, label) =>
  Promise.race([
    p.then((v) => `${label}: resolved ${v}`, (e) => `${label}: rejected ${e.message}`),
    new Promise((r) => setTimeout(() => r(`${label}: still pending after 1s`), 1000)),
  ]);

(async () => {
  console.log(await withTimeout(currentToken(store()), 'call 1 (hung refresh)'));

  // Network recovers; the endpoint now works.
  respond = () =>
    Promise.resolve({ status: 200, ok: true, json: async () => ({ access_token: 'NEW', expires_in: 3600 }) });

  console.log(await withTimeout(currentToken(store()), 'call 2 (endpoint healthy)'));
  console.log('fetch calls total:', calls);
